        "summary": "《EVA》1995 年首播，核心创作期集中在1990–1995 年，也就是日本泡沫经济破裂后的 “失去的十年” 开端，整个作品的压抑、孤独、对自我与人际关系的恐惧、集体心理创伤，全部根植于这一时代独有的社会、经济、文化、青少年心理危机。\n\n\n\n\n\n一、经济背景：泡沫崩……",
        "paragraphs": [
          "《EVA》1995 年首播，核心创作期集中在1990–1995 年，也就是日本泡沫经济破裂后的 “失去的十年” 开端，整个作品的压抑、孤独、对自我与人际关系的恐惧、集体心理创伤，全部根植于这一时代独有的社会、经济、文化、青少年心理危机。\n\n\n\n\n\n一、经济背景：泡沫崩 当我们重新审视《新世纪福音战士》的整体脉络时，会发现创作者并未急于用高密度的戏剧冲突去裹挟观众，而是将叙事重心放在了余韵与留白之上。",
          "在具体的视听与文本结构层面，作品通过细腻的日常细节与回溯式的记忆闪回相互咬合，使每一个看似平淡的桥段都折射出人物内心深处的羁绊与成长。无论是光影色调的冷暖交替，还是关键场景下的静默停顿，都展现出极高的完成度与审美自觉。",
          "许多观众在初看时或许会留意其外在的题材标签，但真正让《新世纪福音战士》在同类作品中脱颖而出的，是它对待「时间」「离别」与「人与人之间如何建立理解」这一核心命题的诚恳态度。[mask]尤其是在中后段情感高潮处，前期的伏笔在一瞬间收束，不靠煽情台词却令人久久无法平息。[/mask]",
          "总的来说，这是一部经得起反复咀嚼与二刷的作品。它不仅在工业水准上交出了令人信服的答卷，更在精神内核上提供了一份温柔而坚韧的慰藉。"
        ],
